// Zone -> globe, par mots-clés (zones renommées ou ajoutées comprises)
window.globeFor = function(nom){
  const n = String(nom).normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase();
  const has = k => n.includes(k);
  if(has("afrique du nord") || has("maghreb") || has("mediterranee")) return "afnord";
  if(has("moyen") || has("golfe") || has("proche")) return "moyenorient";
  if(has("ocean indien") && !has("amerique") && !has("caraibe")) return "oceanindien";
  if(has("caraibe") || has("amerique du sud") || has("amerique latine") || has("antilles") || has("sud")) return has("europe") ? "europesud" : "amsud";
  if(has("amerique") || has("canada") || has("etats")) return "amnord";
  if(has("afrique")) return "afrique";
  if(has("asie") || has("orient") || has("japon") || has("chine")) return "asie";
  if(has("france") || has("domestique") || has("metropole")) return "france";
  if(has("europe du nord") || has("scandinavie") || has("nord")) return "europenord";
  if(has("europe du sud") || has("iberique") || has("italie")) return "europesud";
  if(has("est") || has("centrale")) return "europeest";
  if(has("europe")) return "europe";
  return "monde";
};
